// The three motif PNGs the canvas paints with, generated by assets/gen/gen_art.py.
//
// Loading goes through `Image` rather than `new OffscreenCanvas().convertToBlob()` or fetch: an
// <img> is the one decoder that works identically from http(s), from a Pages sub-path, and from
// file:// — and the offline copy is whatever the service worker already backfilled. A texture that
// never arrives must cost nothing, so nothing here throws and nothing here awaits: the renderer asks
// `motif(name)` every frame and paints the vector fallback while (or after) the bitmap shows up.

const MOTIFS = {
  grain: 'assets/img/board-grain.png',
  ink: 'assets/img/ink-sprite.png',
  hoop: 'assets/img/pulse-hoop.png',
};

const loaded = new Map();
let requested = false;
let readyHook = null;

// 解码完成之后必须有人再画一次：静态盘面下帧循环只给 pulse/墨点重画（js/main.js 的
// `if (pulse || fx.active()) draw()`），而贴图一般在那之后才解码完 —— 于是三张母题 PNG
// 全在盘上却一张都不出现，要到玩家下一次落墨才看见。这里数到三张都 settle 就通知一次。
export function loadMotifs(onReady) {
  if (typeof onReady === 'function') readyHook = onReady;
  if (requested || typeof Image !== 'function') return;
  requested = true;
  let pending = Object.keys(MOTIFS).length;
  const settle = () => {
    if (--pending > 0) return;
    if (typeof readyHook === 'function') readyHook();
  };
  for (const [name, src] of Object.entries(MOTIFS)) {
    const img = new Image();
    img.decoding = 'async';
    img.onload = settle;
    img.onerror = () => {
      loaded.delete(name);
      settle();
    };
    img.src = src;
    loaded.set(name, img);
  }
}

// 注册"贴图落地"之后的重画回调：回调在 loadMotifs 之前挂也认（启动顺序就是先挂再请）。
export function onMotifsReady(fn) {
  readyHook = typeof fn === 'function' ? fn : null;
}

// `complete && naturalWidth` is the readiness test that survives every environment: under a test
// harness or an unsupported decoder the image never completes, and the caller falls back to vector.
export function motif(name) {
  const img = loaded.get(name);
  return img && img.complete && img.naturalWidth ? img : null;
}

export { MOTIFS };
